/**
 * A WebAssembly module, assembled by hand so the tests need no toolchain:
 *
 * (module
 *   (import "host" "log" (func $log (param i32)))
 *   (memory (export "memory") 1)
 *   (func (export "add") (param i32 i32) (result i32)
 *     (call $log (local.get 0))                  ;; calls into JavaScript
 *     (i32.store (i32.const 0) (local.get 1))    ;; writes its own memory
 *     (i32.add (local.get 0) (local.get 1))))
 */
// biome-ignore format: one line per section
export const bytes = new Uint8Array([
	0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, // magic, version
	0x01, 0x0b, 0x02, 0x60, 0x01, 0x7f, 0x00, 0x60, 0x02, 0x7f, 0x7f, 0x01, 0x7f, // types
	0x02, 0x0c, 0x01, 0x04, 0x68, 0x6f, 0x73, 0x74, 0x03, 0x6c, 0x6f, 0x67, 0x00, 0x00, // import host.log
	0x03, 0x02, 0x01, 0x01, // functions
	0x05, 0x03, 0x01, 0x00, 0x01, // memory, 1 page
	0x07, 0x10, 0x02, 0x06, 0x6d, 0x65, 0x6d, 0x6f, 0x72, 0x79, 0x02, 0x00, 0x03, 0x61, 0x64, 0x64, 0x00, 0x01, // exports
	0x0a, 0x14, 0x01, 0x12, 0x00, 0x20, 0x00, 0x10, 0x00, 0x41, 0x00, 0x20, 0x01, 0x36, 0x02, 0x00, 0x20, 0x00, 0x20, 0x01, 0x6a, 0x0b, // code
]);

// The ES library types do not declare WebAssembly; what the tests use of it.
export type Memory = { buffer: ArrayBuffer; grow: (pages: number) => number };
export type Exports = { add: (a: number, b: number) => number; memory: Memory };
export type Instantiate = (
	bytes: Uint8Array,
	imports: object,
) => Promise<{ instance: { exports: Exports } }>;
